import{_ as s,o as i,c as a,a2 as o}from"./chunks/framework.DKc58g3R.js";const u=JSON.parse('{"title":"API — Scheduling","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://pyworkforce.rodrigo-arenas.com/stable/api/scheduling"}],["meta",{"property":"og:url","content":"https://pyworkforce.rodrigo-arenas.com/stable/api/scheduling"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"API — Scheduling"}],["meta",{"property":"og:description","content":"Tools for workforce management: queue staffing (Erlang C / Erlang A), shift scheduling, rostering and operations-research optimization."}],["meta",{"property":"og:image","content":"https://pyworkforce.rodrigo-arenas.com/stable/brand/social-preview.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:image:alt","content":"PyWorkforce shift coverage illustration"}]]},"headers":[],"relativePath":"api/scheduling.md","filePath":"api/scheduling.md","lastUpdated":1795113959000}'),t={name:"api/scheduling.md"};function r(n,e,d,c,l,h){return i(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="api-—-scheduling" tabindex="-1">API — Scheduling <a class="header-anchor" href="#api-—-scheduling" aria-label="Permalink to &quot;API — Scheduling&quot;">​</a></h1><p><code>pyworkforce.scheduling</code></p><p>Both schedulers share the same constructor signature (except <code>cost_dict</code>) and the same <code>solve()</code> output. They validate that every <code>shifts_coverage</code> array and every <code>required_resources</code> row has exactly <code>periods</code> entries.</p><h2 id="minabsdifference" tabindex="-1">MinAbsDifference <a class="header-anchor" href="#minabsdifference" aria-label="Permalink to &quot;MinAbsDifference&quot;">​</a></h2><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MinAbsDifference(num_days, periods, shifts_coverage, required_resources,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                 max_period_concurrency, max_shift_concurrency,</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">                 max_search_time</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">num_search_workers</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">shift_limits</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Minimizes the total absolute difference between required and scheduled resources per period.</p><h2 id="minrequiredresources" tabindex="-1">MinRequiredResources <a class="header-anchor" href="#minrequiredresources" aria-label="Permalink to &quot;MinRequiredResources&quot;">​</a></h2><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MinRequiredResources(num_days, periods, shifts_coverage, required_resources,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                     max_period_concurrency, max_shift_concurrency,</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">                     cost_dict</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">max_search_time</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">240.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">num_search_workers</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">                     *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">shift_limits</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Minimizes the (optionally weighted) number of scheduled resources while covering every period.</p><ul><li><strong>cost_dict</strong> (<code>dict</code>, optional) — <code>{shift_name: cost}</code>; must contain exactly the same shift names as <code>shifts_coverage</code>. Defaults to a cost of <code>1</code> per shift.</li></ul><h2 id="daily-shift-limits" tabindex="-1">Daily shift limits <a class="header-anchor" href="#daily-shift-limits" aria-label="Permalink to &quot;Daily shift limits&quot;">​</a></h2><p>Both schedulers accept <code>shift_limits={(day, shift_name): (minimum, maximum)}</code>. Days are zero-based and bounds are inclusive non-negative integers. The maximum cannot exceed <code>max_shift_concurrency</code>. Unspecified pairs use the global bounds. Fixed limits may still make the model infeasible, for example if their sum exceeds <code>max_period_concurrency</code> during an overlap.</p><h2 id="inspecting-a-solved-schedule" tabindex="-1">Inspecting a solved schedule <a class="header-anchor" href="#inspecting-a-solved-schedule" aria-label="Permalink to &quot;Inspecting a solved schedule&quot;">​</a></h2><p>These methods require the last <code>solve()</code> to have returned <code>OPTIMAL</code> or <code>FEASIBLE</code>. Otherwise they raise <code>RuntimeError</code>.</p><ul><li><code>scheduled_resources()</code> returns <code>{shift_name: [count_day_0, …]}</code> for <code>BreakScheduler</code> or other consumers.</li><li><code>coverage(required_resources=None)</code> returns a pandas DataFrame with <code>day</code>, <code>period</code>, <code>required</code>, <code>scheduled</code>, <code>shortfall</code>, and <code>surplus</code>. Each row represents one zero-based period on one zero-based day. Alternate demand must have shape <code>(num_days, periods)</code> and consist of non-negative 64-bit integers.</li><li><code>compare_coverage(scenarios)</code> takes a non-empty mapping of scenario names to demand arrays. Use <code>None</code> for the original forecast. Each scenario yields <code>required</code>, <code>scheduled</code>, <code>shortfall</code>, and <code>surplus</code> totals in person-periods, plus <code>understaffed_periods</code>. The assignments stay fixed throughout.</li></ul><p>See the <a href="/stable/guide/coverage-scenarios">schedule stress-test tutorial</a>.</p><h2 id="common-parameters" tabindex="-1">Common parameters <a class="header-anchor" href="#common-parameters" aria-label="Permalink to &quot;Common parameters&quot;">​</a></h2><ul><li><strong>num_days</strong> (<code>int</code>) — days to schedule.</li><li><strong>periods</strong> (<code>int</code>) — periods per day.</li><li><strong>shifts_coverage</strong> (<code>dict</code>) — <code>{shift_name: [0/1, …]}</code>, length <code>periods</code>.</li><li><strong>required_resources</strong> (<code>list</code>) — shape <code>[num_days, periods]</code>.</li><li><strong>max_period_concurrency</strong> (<code>int</code>) — max resources per period.</li><li><strong>max_shift_concurrency</strong> (<code>int</code>) — max resources per shift.</li><li><strong>max_search_time</strong> (<code>float</code>) — solver time limit, seconds.</li><li><strong>num_search_workers</strong> (<code>int</code>) — solver worker threads.</li></ul><h2 id="solve" tabindex="-1"><code>solve()</code> <a class="header-anchor" href="#solve" aria-label="Permalink to &quot;\`solve()\`&quot;">​</a></h2><p>Returns a <code>dict</code> (also stored as <code>solution_</code>):</p><ul><li><strong>status</strong> — <code>&quot;OPTIMAL&quot;</code>, <code>&quot;FEASIBLE&quot;</code> or <code>&quot;INFEASIBLE&quot;</code>.</li><li><strong>cost</strong> — objective value (<code>-1</code> if infeasible).</li><li><strong>resources_shifts</strong> — list of <code>{&quot;day&quot;, &quot;shift&quot;, &quot;resources&quot;}</code>.</li></ul><p>See the <a href="/stable/guide/scheduling">scheduling guide</a>.</p>`,22)])])}const g=s(t,[["render",r]]);export{u as __pageData,g as default};
